const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const date=s=>new Date(s).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'});
const roman=['I','II','III','IV','V','VI','VII'];
// Icon paths: Lucide, ISC license. Portrait SVGs are original flat geometric illustrations.
const icons={'arrow-right':'<path d="M5 12h14M12 5l7 7-7 7"/>','arrow-down':'<path d="M12 5v14M5 12l7 7 7-7"/>',x:'<path d="m18 6-12 12M6 6l12 12"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',check:'<path d="m20 6-11 11-5-5"/>',lock:'<rect width="18" height="11" x="3" y="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/>'};
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.classList.add('icon');el.setAttribute('aria-hidden','true');el.innerHTML=`<svg viewBox="0 0 24 24">${icons[el.dataset.icon]||icons['arrow-right']}</svg>`})}
// Use exactly the same SVG facets, proportions and palette as the occupied seats.
const friendSilhouette=portrait({name:'匿名好友',color:'#85866a',hair:'#6c604a',beard:false,style:'guest'},0).replace('<svg ', '<svg class="friend-avatar" ');function portrait(c,index=0){const skin=['#d4b08b','#cda87b','#c69a73','#d9b48a','#c59a77','#d6af84','#d0ac85'][index%7];return `<svg viewBox="0 0 180 240" role="img" aria-label="${esc(c.name)}的低多边形肖像"><path fill="${c.color}" d="M8 240 20 177 62 151 76 140 106 140 120 155 163 181 177 240Z"/><path fill="#e8dfc8" d="m61 152 18-13 25 2 27 21-32 78H35Z"/><path fill="#cfc4aa" d="m77 154 22 14-25 72H35Z"/><path fill="#faf0d5" d="m106 147 23 16-30 77-8-44Z"/><path fill="#b9a88b" d="m45 174 29 12-22 54H25Z"/><path fill="#f0e5ca" d="m126 171 22 18-8 51h-31Z"/><path fill="#ac805e" d="m77 119-2 32 17 20 18-24-5-28Z"/><path fill="${skin}" d="m59 66 16-23 32 1 21 24-2 41-17 29-24 8-23-25-9-30Z"/><path fill="#e7c49a" d="m73 59 16-10 18 3 10 21-12 18-33-9Z"/><path fill="#b78b66" d="m114 66 14 3-2 41-17 29-15 5 8-43Z"/><path fill="#dab18b" d="m61 81 17 12-5 25-12-13Z"/><path fill="#e9c59d" d="m88 85 12-5-3 28-10 3Z"/><path fill="#af815c" d="m98 88 8 23-18 2 9-7Z"/><path fill="#826447" d="m68 84 15-3 2 4-15 3Zm35-1 13 2 3 5-17-3Z"/><path fill="#493d2c" d="m74 89 7-1-2 3h-5Zm31 0 8 1-2 3-7-1Z"/><path fill="${c.hair}" d="m54 81 1-21 13-22 23-7 27 13 15 25-7 14-10-20-10-11-30 5-12 16-1 18Z"/><path fill="#fff4d4" opacity=".25" d="m59 60 20-22 23 2-12 8-18 5-10 20Z"/>${c.style==='chinese'?`<circle cx="90" cy="18" r="13" fill="${c.hair}"/><path fill="#c7a56a" d="M87 5h6v15h-6Z"/>${c.hat==='guan'?`<path fill="#33261b" d="M60 49 69 33l21-6 21 6 9 16-8 5-10-8H78l-10 8Z"/><path fill="#c7a56a" d="M69 33h42v3H69Z"/>`:''}`:''}${c.beard?`<path fill="${c.hair}" d="m61 102 15 15 14-4 12 3 19-13-3 26-14 21-17 4-18-18Z"/><path fill="#fff3d4" opacity=".25" d="m65 113 19 10 3 31-16-19Zm32 10 17-11-10 36-10 3Z"/><path fill="#8d7154" d="m80 120 22 1-10 5Z"/>`:'<path fill="#9c6d51" d="m80 120 20-1-9 5Z"/><path fill="#e4bc92" d="m78 127 21 1-9 7Z"/>'}${c.hat==='laurel'?'<path fill="#b69b57" d="m60 58 10-13 3 10 11-17 1 12 14-12-4 13 16-4-10 10 18 3-17 4-23-5-15 8Z"/>':''}<path fill="#fff5df" opacity=".22" d="m27 188 11-9-8 61H17Zm102-12 11 8-22 56h-13Z"/></svg>`}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function showAiLoading(on){const el=$('#ai-loading');if(el)el.hidden=!on;document.body.classList.toggle('ai-busy',!!on)}
function load(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('浏览器未能保存记录，请检查存储权限');return false}}
let ledger=load('senate-ledger-v1',{balance:0,initialized:false,entries:[],history:[]});
if(!Array.isArray(ledger.entries)||!Array.isArray(ledger.history))ledger={balance:0,initialized:false,entries:[],history:[]};
const ACHIEVEMENTS_SEEN_KEY='senate-achievements-seen-v1';
let achievementSeen=load(ACHIEVEMENTS_SEEN_KEY,null);
let achievementToastQueue=[],achievementToastActive=false;
let credentials=load('senate-session-v1',null),room=null,poll=null,selectedRole=null,tab='history',routing=0;
let profile=load('senate-profile-v1',null)||{};
profile={name:profile.name||'无名公民',motto:profile.motto||'先分辨「想要」与「需要」，再把决定交给时间。',since:profile.since||new Date().toISOString()};
let dev=load('senate-dev-v1',null)||{};
dev={enabled:!!dev.enabled,key:typeof dev.key==='string'?dev.key:'',model:dev.model==='deepseek-reasoner'?'deepseek-reasoner':'deepseek-chat',base:dev.base||'https://api.deepseek.com'};
const devActive=()=>dev.enabled&&!!dev.key.trim();
const devPayload=()=>devActive()?{enabled:true,key:dev.key.trim(),model:dev.model,base:dev.base}:null;
function saveDev(){save('senate-dev-v1',dev)}
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
const homePager={page:0,slide:0,locked:false,lockTimer:null,slideLock:false,slideTimer:null,wheelAcc:0,wheelTimer:null,dragging:false};
let featuredPack='roman',formPack='roman',formSize=5,formSeats=[];
const preferredMotion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
let prefs=load('senate-prefs-v1',{motion:preferredMotion});
const motionOff=()=>!prefs.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;
let ballotTimers=[],typeTimers=[];
const packOf=id=>getPack(id);
const membersOf=id=>getPack(id).members;
const findSage=id=>allMembers.find(c=>c.id===id);
const pad2=n=>String(n).padStart(2,'0');
const sampleIds=(members,n)=>{const ids=members.map(c=>c.id);for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}return ids.slice(0,n)};
const seatPoints=seatPositions;
const homeVisible=()=>{const el=$('#home-view');return !!el&&!el.hidden;};
const dialogOpen=()=>!!document.querySelector('dialog[open]');
function frozen(){return ledger.history.filter(h=>h.decision?.vote==='暂缓'&&new Date(h.freezeUntil)>new Date()).reduce((n,h)=>n+h.price,0)}
function available(){return Math.round((ledger.balance-frozen())*100)/100}
function persistLedger(){save('senate-ledger-v1',ledger);checkAchievements()}
function entry(kind,amount,note){ledger.balance=Math.round((ledger.balance+(kind==='income'?amount:-amount))*100)/100;ledger.entries.unshift({id:crypto.randomUUID(),kind,amount,note,at:new Date().toISOString()});}
async function api(route,{method='GET',body,friendToken}={}){const headers={'Content-Type':'application/json'};if(friendToken)headers['X-Friend-Token']=friendToken;else if(credentials)headers.Authorization=`Bearer ${credentials.ownerToken}`;const response=await fetch(route,{method,headers,body:body?JSON.stringify(body):undefined});let data;try{data=await response.json()}catch{throw Error('会场连接中断，请确认本地服务仍在运行')}if(!response.ok)throw Error(data.error||'操作失败');return data;}
const roomApi=(action,body)=>api(`/api/rooms/${credentials.id}${action?'/'+action:''}`,{method:body===undefined?'GET':'POST',body});
function setView(name){$$('.view').forEach(el=>el.hidden=el.id!==name+'-view');$('#header').classList.toggle('app-header',name!=='home');$('#header').classList.toggle('forum-header',name==='forum'||name==='profile');document.body.classList.toggle('pager-lock',name==='home');if(name!=='home'){$('#header').classList.remove('header-paper');$('#header').classList.remove('header-stage')}$$('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===name||(name==='chamber'&&el.dataset.nav==='forum')));$('#header nav').hidden=name==='friend';}
function openProposal(sample=false){$('#proposal-form').reset();$('#proposal-error').textContent='';resetProposalConfig();if(ledger.initialized)$('#proposal-form [name=cash]').value=Math.max(0,available()).toFixed(2);if(sample)fillSample();$('#proposal-dialog').showModal();}
function applyPrefs(){document.documentElement.classList.toggle('no-motion',!prefs.motion);const btn=$('#motion-toggle');if(btn){btn.classList.toggle('off',!prefs.motion);btn.setAttribute('aria-pressed',String(!prefs.motion));btn.setAttribute('aria-label',prefs.motion?'关闭动画与音效':'开启动画与音效');btn.title=prefs.motion?'关闭动画与音效':'开启动画与音效';const t=btn.querySelector('.pref-text');if(t)t.textContent=prefs.motion?'动效 开':'动效 关'}if(!prefs.motion){const hero=$('.hero');if(hero){hero.style.setProperty('--mx','0');hero.style.setProperty('--my','0')}}}
function drawFormSeats(){formSeats=sampleIds(membersOf(formPack),formSize)}
function renderPackOptions(){const root=$('#pack-options');if(!root)return;root.innerHTML=packList.map(p=>`<button type="button" class="pack-card ${p.id===formPack?'active':''} ${p.locked?'locked':''}" data-pack-option="${p.id}" ${p.locked?'disabled aria-disabled="true"':''} aria-pressed="${p.id===formPack}" title="${p.locked?'待解锁':p.name}"><span class="pack-crest">${p.crest}</span><span class="pack-name">${p.name}</span><span class="pack-sub">${p.locked?'后续开放':p.tagline}</span>${p.locked?'<span class="pack-lock">待解锁</span>':''}</button>`).join('')}
function renderSizeOptions(){const root=$('#size-options');if(!root)return;root.innerHTML=sizes.map(n=>`<button type="button" class="size-card ${n===formSize?'active':''}" data-size-option="${n}" aria-pressed="${n===formSize}"><b>${n}</b><span>人 · ${sizeLabels[n]}</span></button>`).join('')}
function renderCouncilPreview(){
  const root=$('#council-preview');if(!root)return;
  const pack=packOf(formPack),points=previewPositions(formSize);
  const selected=formSeats.map(id=>pack.members.find(c=>c.id===id)).filter(Boolean);
  root.dataset.pack=pack.theme;
  $('#council-summary').textContent=`${formSize} 位 · ${pack.name}`;
  root.innerHTML=`<div class="mini-ring pack-${pack.theme}" data-size="${formSize}">${selected.map((c,i)=>`<div class="mini-seat lit" style="--x:${points[i][0]}%;--y:${points[i][1]}px"><span class="mini-bust">${portrait(c,pack.members.indexOf(c))}</span><span class="mini-name">${esc(c.name)}</span></div>`).join('')}<div class="mini-floor">${formSize} SEATS · ${pack.short}</div></div><p class="preview-note">中央一席 · 两侧各 ${(formSize-1)/2} 席 · 随机入选，不重复</p>`;
}
function renderProposalConfig(){renderPackOptions();renderSizeOptions();renderCouncilPreview()}
function resetProposalConfig(){formPack='roman';formSize=5;drawFormSeats();renderProposalConfig();renderSlideVoices(formPack)}
function selectFormPack(id){if(!packs[id])return;formPack=id;drawFormSeats();renderProposalConfig();renderSlideVoices(id)}
function selectFormSize(n){if(!sizes.includes(Number(n)))return;formSize=Number(n);drawFormSeats();renderProposalConfig()}
function fillSample(){const f=$('#proposal-form');f.product.value='Sony WH-1000XM5 降噪耳机';f.price.value='1799';f.cash.value=ledger.initialized?Math.max(0,available()).toFixed(2):'6000';f.reason.value='每天在自习室学习，也常坐地铁。想要更安静的环境，但现有的耳机还可以用。';}
function renderSlideVoices(packId=featuredPack){featuredPack=packId;const root=$('#slide-voices');if(!root)return;const pack=packOf(packId);const shot=$('.ritual-slide[data-slide="4"] .shot-frame img');if(shot){shot.src=pack.id==='chinese'?'/assets/shots/council-chinese.jpg':'/assets/shots/seven-roman.jpg';shot.alt=`${pack.name}的议事厅`}root.innerHTML=pack.members.map((c,i)=>`<button type="button" class="sage-card" data-sage="${c.id}" style="--i:${i}" title="${esc(c.question)}"><span class="sage-arch">${portrait(c,i)}</span><span class="sage-name">${c.name}</span><span class="sage-lens">${c.lens}</span><span class="sage-mbti">${c.mbti}</span></button>`).join('')}
function showSage(id){const c=findSage(id);if(!c)return;const pack=Object.values(packs).find(p=>p.members.some(m=>m.id===id))||packs.roman;const index=pack.members.indexOf(c);$('#detail-content').innerHTML=`<div class="sage-detail"><div class="sage-detail-portrait">${portrait(c,index)}</div><div class="sage-detail-body"><p class="eyebrow">${c.en} · ${c.lens} · ${c.mbti}</p><h2>${c.name}</h2><p class="sage-question">${c.question}</p><p class="desk-note">${pack.name} · 在议事厅中，${c.name}会以此问题质询你。</p></div></div>`;$('#detail-dialog').showModal()}
function splitChars(el,start=0){let i=start;const frag=document.createDocumentFragment();for(const ch of el.textContent){const s=document.createElement('span');s.className='ch';s.style.setProperty('--i',i++);s.textContent=ch===' '?'\u00a0':ch;frag.appendChild(s)}el.textContent='';el.appendChild(frag);return i}
function splitHero(){const eyebrow=document.querySelector('.hero-eyebrow');if(eyebrow&&!eyebrow.querySelector('.ch'))splitChars(eyebrow);const h=$('#hero-title');if(h&&!h.querySelector('.ch')){let i=0;h.querySelectorAll('em,span').forEach(part=>{i=splitChars(part,i)})}}
function activateScreen(page){const screens=$$('.pager-screen');screens.forEach((s,i)=>{if(i===page)return;clearTimeout(s._animOut);s._animOut=setTimeout(()=>{if(homePager.page!==i)s.classList.remove('animate')},1050)});const screen=screens[page];if(screen){clearTimeout(screen._animOut);screen.classList.remove('animate');void screen.offsetWidth;screen.classList.add('animate')}}
function setPagerPage(page,{instant=false}={}){page=clamp(page,0,2);homePager.page=page;try{history.replaceState(null,'',page===2?'#forum':'#home')}catch{}const pager=$('#home-pager'),track=$('#pager-track');if(pager)pager.dataset.page=page;if(track){if(instant){track.style.transition='none';track.style.transform=`translateY(-${page*100}%)`;void track.offsetWidth;track.style.transition=''}else{track.style.transform=`translateY(-${page*100}%)`}}$$('.pager-screen').forEach((s,i)=>{s.classList.toggle('is-active',i===page);s.inert=i!==page});$$('.pager-dots button').forEach((b,i)=>b.classList.toggle('active',i===page));$$('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===(page===2?'forum':'home')));$('#header').classList.toggle('header-stage',page===1);if(page===2)renderForum();activateScreen(page)}
function goPage(page){if(!homeVisible()||homePager.locked)return;const target=clamp(page,0,2);if(target===homePager.page)return;homePager.locked=true;homePager.lockTimer=setTimeout(()=>{homePager.locked=false},1050);setPagerPage(target)}
function setSlide(index){index=clamp(index,0,4);const current=document.querySelector('.ritual-slide.is-active');if(current&&Number(current.dataset.slide)!==index){current.classList.add('is-leaving');clearTimeout(current._leaveTimer);current._leaveTimer=setTimeout(()=>current.classList.remove('is-leaving'),900)}homePager.slide=index;const track=$('#ritual-track');if(track)track.style.transform=`translateX(-${index*100}%)`;$$('.ritual-slide').forEach((s,i)=>{s.classList.toggle('is-active',i===index);s.inert=i!==index});$$('[data-slide-to]').forEach(b=>{const on=Number(b.dataset.slideTo)===index;b.classList.toggle('active',on);if(b.getAttribute('role')==='tab')b.setAttribute('aria-selected',String(on))});const count=$('.slide-count');if(count)count.textContent=`${String(index+1).padStart(2,'0')} / 05`}
function goSlide(index){if(!homeVisible())return;const target=clamp(index,0,4);if(target!==homePager.slide)setSlide(target)}
function slideBy(dir){if(homePager.slideLock)return;homePager.slideLock=true;clearTimeout(homePager.slideTimer);homePager.slideTimer=setTimeout(()=>{homePager.slideLock=false},700);goSlide(homePager.slide+dir)}
function phaseIndex(){return room.state==='CREATED'?0:room.state==='QUESTIONING'?1:['QUESTION_DONE','WAIT_FRIEND_SUBMIT'].includes(room.state)?2:3;}
function scene(){const members=membersOf(room.pack),total=room.seats.length,points=seatPoints(total),pack=packOf(room.pack);return `<div class="scene"><div class="architecture" aria-hidden="true">${Array(7).fill('<div class="arch"></div>').join('')}</div><div class="scene-label">${pack.mark} · ${room.state==='CREATED'?`${total} SEATS`:'IN SESSION'}</div>${room.seats.map((id,i)=>{const c=members.find(c=>c.id===id),f=room.friends?.find(f=>f.seat===i),nm=c?.name||f?.name||'好友席',active=room.state==='QUESTIONING'&&room.answers.length===i;return `<div class="seat ${room.state==='CREATED'?'editable':''} ${active?'active':''}" style="--x:${points[i][0]}%;--y:${points[i][1]}px" ${room.state==='CREATED'?`role="button" tabindex="0" data-seat="${i}" aria-label="替换第${i+1}席 ${esc(nm)}"`:''}><div class="bust">${c?portrait(c,members.indexOf(c)):friendSilhouette}</div><div class="plinth"></div><span class="seat-name">${esc(nm)}</span><span class="seat-status">${active?(f&&!f.questionAsked?'等待好友提问':'正在质询'):room.state==='CREATED'?`${roman[i]} · ${c?.lens||'独立意见'}${c?.mbti?' · '+c.mbti:''}`:room.answers.length>i?'已答复':f?(f.questionAsked?'待答复':'待提问'):`${roman[i]}${c?' · '+c.mbti:''}`}</span></div>`}).join('')}<div class="floor-mark">${room.state==='CREATED'?'THE FLOOR IS YOURS':'YOU ARE AT THE CENTRE'}</div></div>`}
function setupDesk(){const members=membersOf(room.pack),pack=packOf(room.pack),total=room.seats.length;return `<div class="desk-heading"><h3>${total} 席就位，等待开庭</h3><span class="eyebrow">COMPOSE YOUR COUNCIL</span></div><p class="desk-note">拖动头像到席位，或先点选头像、再点席位。开始质询后席位锁定。</p><div class="seat-pool-wrap"><div class="seat-pool">${members.map((c,i)=>`<button class="pool-chip ${selectedRole===c.id?'selected':''}" draggable="true" data-role="${c.id}" title="${c.name} · ${c.lens} · ${c.mbti}" aria-label="选择${c.name}">${portrait(c,i)}</button>`).join('')}<button class="pool-chip friend ${selectedRole==='friend'?'selected':''}" draggable="true" data-role="friend" title="好友席" aria-label="选择好友席">${friendSilhouette}</button></div><p class="selection-hint">${selectedRole?`已选${members.find(c=>c.id===selectedRole)?.name||'好友席'}，点击上方席位替换`:`${pack.name} · ${total} 席 · 好友可替换任意席位`}</p></div><div class="desk-actions"><span class="demo-label">${room.seats.includes('friend')?'混合议会 · 全员提交后揭晓':`${pack.name} · ${total} 席独立表态`}</span><button class="button primary" data-action="start">开启质询 <i data-icon="arrow-right"></i></button></div>`}
function questionDesk(){const total=room.questions.length,i=room.answers.length,q=room.questions[i];if(q?.friendSeat&&!q.question)return waitingQuestionDesk(q);return `<form id="answer-form"><div class="desk-heading"><div><p class="eyebrow">${q.en||'A QUESTION FOR YOU'}${q.mbti?' · '+q.mbti:''}</p><h3 style="margin-top:8px">${esc(q.name)}的质询</h3></div><span class="question-count">${pad2(i+1)} <small>/ ${pad2(total)}</small></span></div><p class="question-text" aria-label="${esc(q.question)}"><span class="question-space" aria-hidden="true">${esc(q.question)}</span><span class="question-reveal" aria-hidden="true">${esc(q.question)}</span></p><label class="sr-only" for="answer-input">你的回答</label><textarea id="answer-input" class="answer-area" name="answer" rows="2" required maxlength="1500" placeholder="不必给出完美答案，只需诚实地说说你的想法…"></textarea><div class="desk-actions"><button type="button" class="text-link" style="margin:0" data-action="transcript">查看已答问询</button><button type="submit" class="button primary">${i===total-1?'完成质询':'呈上回答'} <i data-icon="arrow-right"></i></button></div><div class="progress-line"><span style="width:${(i+1)/total*100}%"></span></div></form>`}
function waitingQuestionDesk(q){const total=room.questions.length,i=room.answers.length,fi=room.friends.findIndex(f=>f.seat===q.seat),f=room.friends[fi];return `<div class="desk-heading"><div><p class="eyebrow">A FRIEND'S QUESTION</p><h3 style="margin-top:8px">等待好友提出质询</h3></div><span class="question-count">${pad2(i+1)} <small>/ ${pad2(total)}</small></span></div><p class="desk-note">第 ${i+1} 席是好友席。好友席的问题不能由先贤代拟，也不会预先加载：请把邀请链接发给好友，等 TA 写下自己的问题、你回答之后，才会继续下一条质询。<strong>全部质询结束后才开始表决。</strong></p>${f?`<div class="invite-row"><span>第 ${f.seat+1} 席 · 好友${f.name?` · ${esc(f.name)}`:''}</span><button data-action="copy-invite" data-index="${fi}">复制邀请链接</button><a href="${friendHref(f)}" target="_blank" rel="noopener">打开好友页</a></div>`:''}<div class="desk-actions"><button type="button" class="text-link" style="margin:0" data-action="transcript">查看已答问询</button><button type="button" class="button primary" data-action="refresh">刷新状态 · 等待好友提问 <i data-icon="arrow-right"></i></button></div><p class="desk-note" style="margin-top:10px">页面每 3 秒自动检查一次；好友提问后会在这里逐字呈现。</p><div class="progress-line"><span style="width:${(i+1)/total*100}%"></span></div>`}
function doneDesk(){const total=room.questions.length;return `<div class="desk-heading"><h3>${pad2(total)} 次质询，已全部答复</h3><span class="eyebrow">THE DELIBERATION</span></div><p class="desk-note">你的回答已封存。议员将从各自的角度给出观点，并在「买」「暂缓」「不买」之间表态。</p><div class="desk-actions"><button class="text-link" style="margin:0" data-action="transcript">回顾完整问答</button><button class="button primary" data-action="deliberate">进入观点与投票 <i data-icon="arrow-right"></i></button></div>`}
function friendHref(f){return `${location.origin}/#friend/${room.id}/${f.token}`}
function inquiryInvites(){
  if(room.state!=='QUESTIONING'||!room.friends.length)return '';
  const pending=room.friends.filter(f=>!f.questionAsked).length;
  return `<details class="inquiry-invites" open><summary>好友质询 · ${pending?`还有 ${pending} 位待提问`:'已全部提问'}</summary><p class="desk-note">${pending?'现在即可邀请好友写下自己的问题。按席位依次答复后，才会进入表决。':'好友的质询已全部送达；回答完当前问题后才会进入表决。'}</p>${room.friends.map((f,i)=>`<div class="invite-row"><span>第 ${f.seat+1} 席 · ${esc(f.name||'好友')} · ${f.questionAsked?'已提问':'待提问'}</span><button type="button" data-action="copy-invite" data-index="${i}">复制邀请链接</button><a href="${friendHref(f)}" target="_blank" rel="noopener">打开好友页</a></div>`).join('')}</details>`;
}
function waitingDesk(){const total=room.seats.length,submitted=room.friends.filter(f=>f.submitted).length,sealed=total-room.friends.length+submitted;return `<div class="desk-heading"><h3>观点封存，等待好友</h3><span class="eyebrow">SEALED UNTIL ALL VOTE</span></div><div class="waiting-symbol">${sealed}<span style="font-size:20px"> / ${total}</span></div><p class="waiting-copy">先贤观点已封存。好友只能看到商品与完整问答<br>${total} 席全部提交后，观点与票数一起揭晓</p>${room.friends.map((f,i)=>`<div class="invite-row"><span>第 ${f.seat+1} 席 · 好友 ${i+1}</span>${f.submitted?'<span style="color:#6f7f5a">已封存</span>':`<button data-action="copy-invite" data-index="${i}">复制邀请链接</button><a href="${friendHref(f)}" target="_blank" rel="noopener">打开好友页 ↗</a>`}</div>`).join('')}<div class="desk-actions"><span class="demo-label">会场会自动更新</span><button class="text-link" style="margin:0" data-action="refresh">刷新提交状态</button></div>`}
function voteCountMarkup(ballots,revealed=ballots.length){const shown=ballots.slice(0,revealed),tally=Object.fromEntries(votes.map(v=>[v,shown.filter(b=>b.vote===v).length]));return `<div class="vote-counts"><div class="buy"><strong>${tally['买']}</strong><small>买</small></div><div><strong>${tally['暂缓']}</strong><small>暂缓</small></div><div class="no"><strong>${tally['不买']}</strong><small>不买</small></div></div>`}
function minoritySeats(ballots){const counts=Object.fromEntries(votes.map(v=>[v,ballots.filter(b=>b.vote===v).length])),max=Math.max(...Object.values(counts)),set=new Set();if(max>0&&new Set(ballots.map(b=>b.vote)).size>1)ballots.forEach(b=>{if(counts[b.vote]<max)set.add(b.seat)});return set}
function opinionRowMarkup(b,i,minority,typing=false){const isMinority=minority.has(b.seat);return `<article class="opinion-row ballot-in ${isMinority?'minority':''}" style="--i:${i}" data-seat="${b.seat}"><header><span>${esc(b.name)} ${b.source==='friend'?'<small>· 好友</small>':''}${isMinority?'<span class="minority-tag">少数派</span>':''}</span><span class="vote-badge">${b.vote}</span></header><p class="opinion-copy${typing?' typing':''}">${typing?'':esc(b.opinion.replace(/【(买|暂缓|不买)】\s*$/,''))}</p></article>`}
function ballotMarkup(r){const minority=minoritySeats(r.ballots);return `${voteCountMarkup(r.ballots)}<div class="opinion-list">${[...r.ballots].sort((a,b)=>a.seat-b.seat).map((b,i)=>opinionRowMarkup(b,i,minority)).join('')}</div>`}
function clearBallotReveal(){ballotTimers.forEach(clearTimeout);ballotTimers=[];typeTimers.forEach(clearInterval);typeTimers=[]}
function finishTyping(){typeTimers.forEach(clearInterval);typeTimers=[];document.querySelectorAll('.typing').forEach(el=>{if(el.dataset.fullText!==undefined)el.textContent=el.dataset.fullText;el.classList.remove('typing')})}
function typewrite(el,text,delay=14){
  if(!el)return;el.dataset.fullText=text;el.classList.remove('typing');
  if(motionOff()||!text){el.textContent=text;return}
  const chars=Array.from(text);let index=0;el.textContent='';el.classList.add('typing');
  const timer=setInterval(()=>{
    if(!el.isConnected){clearInterval(timer);typeTimers=typeTimers.filter(t=>t!==timer);return}
    el.textContent+=chars[index++];
    if(index>=chars.length){clearInterval(timer);el.classList.remove('typing');typeTimers=typeTimers.filter(t=>t!==timer)}
  },delay);typeTimers.push(timer);
}
function setupBallotReveal(){clearBallotReveal();const stage=$('#ballot-stage'),status=$('#ballot-status'),counts=$('#vote-counts'),decision=$('#decision-area'),heading=$('#result-heading'),note=$('#ballot-note');if(!stage)return;const ballots=[...room.ballots].sort((a,b)=>a.seat-b.seat),minority=minoritySeats(ballots);const finish=()=>{if(status)status.textContent='全部选票已揭晓 · 决定权在你';if(heading)heading.textContent='议会已表态，决定权在你';if(note)note.textContent=minority.size?'少数派观点已高亮 · 仅供参考':'投票仅供参考，最终决定权始终在你';if(decision)decision.hidden=false;stage.classList.add('done')};if(!ballots.length){finish();return}if(room.decision||motionOff()){stage.innerHTML=ballots.map((b,i)=>opinionRowMarkup(b,i,minority)).join('');if(counts)counts.innerHTML=voteCountMarkup(ballots);if(decision)decision.hidden=false;if(room.decision&&status)status.textContent='选票已全部揭晓';else finish();return}let i=0;const step=()=>{if(!document.body.contains(stage))return;const b=ballots[i];stage.insertAdjacentHTML('beforeend',opinionRowMarkup(b,i,minority,true));const row=stage.lastElementChild,copy=row?.querySelector('.opinion-copy');typewrite(copy,b.opinion.replace(/【(买|暂缓|不买)】\s*$/,''));i++;if(counts)counts.innerHTML=voteCountMarkup(ballots,i);if(status)status.textContent=`正在开启第 ${i} / ${ballots.length} 张选票…`;if(i<ballots.length)ballotTimers.push(setTimeout(step,950));else ballotTimers.push(setTimeout(finish,650))};ballotTimers.push(setTimeout(step,450))}
function resultsDesk(){const decided=!!room.decision,total=room.seats.length,decision=decided?`<div class="decision-area" id="decision-area"><h3>你的决定 · ${room.decision.vote}${room.decision.days?` ${room.decision.days} 天`:''}</h3><p class="waiting-copy" style="margin-top:16px">已记入你的消费历史</p><div class="decision-options"><a class="button" href="#ledger">查看账本</a><button class="button primary" data-action="new">召集下一场议会</button></div></div>`:`<div class="decision-area" id="decision-area" hidden><h3>听完之后，你的选择是</h3><div class="decision-options">${votes.map(v=>`<button class="button ${v==='买'?'primary':''}" data-action="decide" data-vote="${v}">${v==='买'?'决定购买':v==='暂缓'?'先冷静一下':'决定不买'}</button>`).join('')}</div><label class="freeze-row" style="display:block">选择暂缓时，冻结预算<select id="freeze-days"><option value="3">3 天</option><option value="7">7 天</option></select>到期自动释放</label></div>`;return `<div class="desk-heading"><h3 id="result-heading">${decided?'议会已表态，决定权在你':'选票将逐一揭晓'}</h3><span class="eyebrow">THE FINAL WORD</span></div><div id="vote-counts">${voteCountMarkup(decided?room.ballots:[],0)}</div><p class="ballot-status" id="ballot-status">${decided?'选票已全部揭晓':`正在开启第 0 / ${total} 张选票…`}</p><div class="opinion-list ballot-stage" id="ballot-stage" aria-live="polite"></div>${decision}<p class="ballot-note" id="ballot-note"></p>`}
function renderChamber(){clearBallotReveal();if(!room){$('#chamber-view').innerHTML=`<section class="hall-empty"><p class="eyebrow">THE ASSEMBLY AWAITS</p><h1>The Senate</h1><h2>你的议会，尚未开庭</h2><p>呈上一件让你犹豫的商品<br>让先贤陪你想清楚</p><button class="button primary" data-action="new">召集元老院</button></section>`;return;}const pack=packOf(room.pack),aiLine=room.devWarning?'DeepSeek 未连接 · 本地回退':(room.questionEngine==='deepseek'&&(!room.ballotEngine||room.ballotEngine==='deepseek')?`DeepSeek · ${esc(room.devModel||'deepseek-chat')} · 先贤在线`:room.questionEngine==='deepseek'?'DeepSeek 质询 · 本地表态':room.ballotEngine==='deepseek'?'本地质询 · DeepSeek 表态':`演示模式 · ${pack.name} · 先贤问答与观点由本地规则模拟`),content={CREATED:setupDesk,QUESTIONING:questionDesk,QUESTION_DONE:doneDesk,WAIT_FRIEND_SUBMIT:waitingDesk,VOTE_FINISHED:resultsDesk}[room.state];$('#chamber-view').innerHTML=`<section class="chamber pack-${room.pack}"><div class="chamber-topbar"><div class="room-title"><p class="eyebrow">ASSEMBLY ${room.id.slice(0,6).toUpperCase()} · ${pack.short}</p><h2>${esc(room.product)}<span>¥ ${money(room.price)}</span></h2></div><div class="phase-track">${['召集','质询','封存','裁决'].map((s,i)=>`<span class="${i===phaseIndex()?'active':''}"><b>0${i+1}</b>${s}</span>`).join('')}</div><div class="room-tools">${(room.questionEngine==='deepseek'||room.ballotEngine==='deepseek')?'<span class="ai-badge">DEEPSEEK</span>':''}<button data-action="transcript">议事记录</button><button data-action="new">新议会 +</button></div></div>${scene()}<div class="council-desk">${content()}${inquiryInvites()}</div><div class="chamber-bottom"><span>投票仅供参考，最终决定权始终在你</span><span title="${esc(room.devWarning||'')}"><i class="status-dot"></i>${aiLine}</span></div></section>`;hydrateIcons($('#chamber-view'));setupPolling();const currentQ=room.questions?.[room.answers.length];if(room.state==='QUESTIONING'&&currentQ?.question){const qText=$('.question-reveal');if(qText)typewrite(qText,qText.textContent,60)}if(room.state==='VOTE_FINISHED')setupBallotReveal();}
function setupPolling(){clearInterval(poll);poll=null;if(!room||location.hash!=='#chamber')return;const q=()=>room.questions?.[room.answers.length];const pendingFriend=room.state==='QUESTIONING'&&q()?.friendSeat&&!q()?.question;if(room.state!=='WAIT_FRIEND_SUBMIT'&&!pendingFriend)return;poll=setInterval(async()=>{try{const r=await roomApi('');if(location.hash!=='#chamber'){clearInterval(poll);poll=null;return}const arrived=r.questions?.some((x,i)=>x.friendSeat&&x.question&&!room.questions?.[i]?.question);const changed=r.state!==room.state||r.answers.length!==room.answers.length||r.questions?.some((x,i)=>x.question!==room.questions?.[i]?.question)||r.friends.filter(f=>f.submitted).length!==room.friends.filter(f=>f.submitted).length;if(changed){room=r;renderChamber();if(arrived)toast('好友的质询已送达，正在逐字呈现');if(r.state==='VOTE_FINISHED')toast('全部席位已提交，议会结果揭晓')}}catch{clearInterval(poll);poll=null;toast('会场连接中断，点击刷新可重试')}},3000);}
function transcriptMarkup(answers){return answers.length?answers.map((q,i)=>`<article class="qa-row"><small>${roman[i]} · ${esc(q.name)}</small><h3>${esc(q.question)}</h3><p>${esc(q.answer)}</p></article>`).join(''):'<p class="muted" style="margin:25px 0">还没有提交的回答</p>'}
function showTranscript(){if(!room)return;const total=room.questions?.length||room.seats.length;$('#detail-content').innerHTML=`<p class="eyebrow">ASSEMBLY RECORD</p><div class="record-heading"><h2>${esc(room.product)}</h2><p>¥ ${money(room.price)} · ${room.answers.length} / ${total} 次质询 · ${esc(room.packName||packOf(room.pack).name)}</p></div><p class="user-reason">${esc(room.reason)}</p>${transcriptMarkup(room.answers)}`;$('#detail-dialog').showModal()}
async function assignSeat(i){if(room?.state!=='CREATED')return;if(!selectedRole){toast('请先选择下方一位先贤或好友头像');return;}const seats=[...room.seats];if(selectedRole==='friend'){const old=seats.indexOf('friend');if(old>=0&&old!==i)seats[old]=seats[i];seats[i]='friend'}else{const old=seats.indexOf(selectedRole);if(old>=0&&old!==i)seats[old]=seats[i];seats[i]=selectedRole}if(seats.every((s,k)=>s===room.seats[k])){selectedRole=null;renderChamber();return}room=await roomApi('seats',{seats});selectedRole=null;renderChamber()}
function recordDecision(){if(!room?.decision||ledger.history.some(h=>h.id===room.id))return;const record=JSON.parse(JSON.stringify(room));delete record.friends;record.councilSize=room.seats.length;record.packId=room.pack;record.packName=room.packName||packOf(room.pack).name;record.freezeUntil=room.decision.vote==='暂缓'?new Date(Date.now()+room.decision.days*864e5).toISOString():null;ledger.history.unshift(record);if(room.decision.vote==='买')entry('expense',room.price,room.product);persistLedger();}
function historyMarkup(){if(!ledger.history.length)return `<div class="empty-state"><div class="empty-icon">VII</div><h3>每一次选择，都值得被记住</h3><p>完成第一场议会后，你的决定和完整问答会出现在这里</p><button class="button" data-action="new">召集第一场议会</button></div>`;return ledger.history.map(h=>{const waiting=h.decision.vote==='暂缓',active=waiting&&new Date(h.freezeUntil)>new Date();return `<article class="history-card"><time class="history-date">${date(h.createdAt)}</time><div class="history-info"><h3>${esc(h.product)}</h3><p class="history-pack">${esc(h.packName||packOf(h.packId).name)} · ${h.councilSize||h.seats?.length||7} 席</p><p>${h.decision.vote}${waiting?active?` · 冷静期至 ${date(h.freezeUntil)}`:' · 冷静期已结束，冻结预算已释放':''} · ${h.ballots.filter(b=>b.vote==='买').length} 票买 / ${h.ballots.filter(b=>b.vote==='暂缓').length} 票暂缓 / ${h.ballots.filter(b=>b.vote==='不买').length} 票不买</p></div><strong class="history-amount">¥ ${money(h.price)}</strong><div class="history-actions"><button data-action="record" data-id="${h.id}">完整记录</button>${waiting?`<button data-action="resolve" data-id="${h.id}" data-vote="买">确认购买</button><button data-action="resolve" data-id="${h.id}" data-vote="不买">放弃购买</button>`:''}</div></article>`}).join('')}
function entriesMarkup(){return `<form id="money-form" class="money-form"><label>类型<select name="kind"><option value="income">收入</option><option value="expense">支出</option></select></label><label>金额 · ¥<input name="amount" type="number" required min="0.01" max="1000000000" step="0.01" placeholder="0.00"></label><label>备注<input name="note" required maxlength="100" placeholder="例如：本月可用预算"></label><button class="button primary" type="submit">记一笔</button></form>${ledger.entries.length?ledger.entries.map(e=>`<article class="entry-row"><small>${date(e.at)}</small><span>${esc(e.note)}</span><strong style="color:${e.kind==='income'?'#6b7c59':'#9c6d52'}">${e.kind==='income'?'+':'−'} ¥ ${money(e.amount)}</strong></article>`).join(''):'<div class="empty-state"><h3>从第一笔预算开始</h3><p>记录收入与支出，知道自己还有多少选择的余地</p></div>'}`}
function renderLedger(){$('#ledger-view').innerHTML=`<section class="ledger-page"><div class="ledger-hero"><img src="/assets/ledger-desk.svg" alt="古罗马书桌上的账本、雅典海景、羽毛笔与金币"><div class="ledger-hero-copy"><strong>The Ledger</strong><span>桌案、海风，与每一次决定</span></div></div><div class="ledger-sheet"><div class="page-title"><div><p class="eyebrow">THE LEDGER & ARCHIVES</p><h1>记账与历史</h1></div><button class="button" data-action="new">召集新议会 +</button></div><div class="stat-row"><article><small>当前可用闲钱</small><strong>¥ ${money(available())}</strong></article><article><small>冷静期冻结</small><strong>¥ ${money(frozen())}</strong></article><article><small>已完成议会</small><strong>${String(ledger.history.length).padStart(2,'0')}</strong></article></div><div class="ledger-tabs"><button class="${tab==='history'?'active':''}" data-action="ledger-tab" data-tab="history">议会历史</button><button class="${tab==='entries'?'active':''}" data-action="ledger-tab" data-tab="entries">收支账本</button></div>${tab==='history'?historyMarkup():entriesMarkup()}<p class="ledger-notice" style="margin-top:35px">账本保存在当前浏览器。冷静期结束后冻结预算自动释放；确认购买才计入支出。</p></div></section>`;hydrateIcons($('#ledger-view'))}
function renderForum(){
  document.querySelectorAll('.forum-identity').forEach(el=>{el.textContent=`以 ${profile.name} 的身份入席`});
  document.querySelectorAll('.forum-session-note').forEach(note=>{
    if(room){const phase=['召集','质询','封存','裁决'][phaseIndex()];note.textContent=`第 ${String(ledger.history.length+1).padStart(2,'0')} 场 · ${room.product} · ${phase}`}
    else if(credentials)note.textContent='上一场议会仍在等待';
    else note.textContent='你的议会，尚未开庭';
  });
  document.querySelectorAll('.forum-resume').forEach(el=>{el.hidden=!credentials});
  document.querySelectorAll('.portal-council').forEach(el=>el.setAttribute('aria-label','召集元老院，开始一场新的议会'));
}
function devPanelMarkup(){
  const status=devActive()?'已配置 · 新议会生效':(dev.enabled?'请填写 API Key':'填写 Key 后开启');
  return `<section class="dev-panel" id="dev-panel"><header><div><p class="eyebrow">DEVELOPER MODE</p><h2>先贤引擎 · DeepSeek</h2></div><label class="dev-toggle"><input type="checkbox" id="dev-enabled" ${dev.enabled?'checked':''}><span class="dev-track"><span class="dev-thumb"></span></span><b>${dev.enabled?'已开启':'未开启'}</b></label></header><p class="dev-note">开启后，新议会的先贤质询与表态由 DeepSeek 实时生成；关闭或连接失败时自动回退本地规则。API Key 只保存在当前浏览器。</p><form id="dev-form" class="dev-form"><div id="dev-fields" ${dev.enabled?'':'hidden'}><label>DeepSeek API Key<input name="key" type="password" value="${esc(dev.key)}" placeholder="sk-..." autocomplete="off" spellcheck="false"></label><div class="dev-row"><label>模型<select name="model"><option value="deepseek-chat" ${dev.model==='deepseek-chat'?'selected':''}>deepseek-chat · 快速</option><option value="deepseek-reasoner" ${dev.model==='deepseek-reasoner'?'selected':''}>deepseek-reasoner · 深思</option></select></label><label>Base URL<input name="base" type="url" value="${esc(dev.base)}" placeholder="https://api.deepseek.com" autocomplete="off" spellcheck="false"></label></div><div class="dev-actions"><button class="button primary" type="submit">保存开发者设置</button><button class="button dev-test" type="button" data-action="dev-test">测试连接</button><span id="dev-status" class="dev-status ${devActive()?'ok':''}">${status}</span></div><p class="dev-security">Key 不会写入会场或账本；只在测试 / 开启质询 / 表决时发送给当前部署的服务，由它转发 DeepSeek。</p></div></form></section>`;
}
function achievementsMarkup(){
  const medals=evaluateAchievements(ledger),unlocked=medals.filter(m=>m.unlocked).length;
  return `<section class="achievement-gallery" id="achievement-gallery" aria-labelledby="achievement-title"><header class="achievement-heading"><div><p class="eyebrow">HONORES · THE SEVEN VIRTUES</p><h2 id="achievement-title">成就勋章</h2><p>每一次认真思考，都有迹可循。点击勋章，查看它的故事与达成条件。</p></div><div class="achievement-counter" aria-label="已点亮 ${unlocked} 枚，共 7 枚"><strong>${unlocked}</strong><span>/ 7</span> 已点亮</div></header><div class="achievement-grid">${medals.map(m=>`<button type="button" class="achievement-card ${m.unlocked?'is-unlocked':'is-locked'}" data-action="achievement" data-achievement="${m.id}" aria-label="${esc(m.name)}，${m.unlocked?'已点亮':'未解锁'}。${esc(m.condition)}当前进度 ${m.progress}/${m.target}"><img class="achievement-art" src="${m.icon}" width="160" height="160" loading="lazy" decoding="async" alt="${esc(m.symbol)}勋章"><span class="achievement-state">${m.unlocked?'✦ 已点亮':'尚未解锁'}</span><strong>${esc(m.name)}</strong><span class="achievement-condition">${esc(m.condition)}</span><progress class="achievement-meter" max="${m.target}" value="${m.progress}" aria-label="${esc(m.name)}达成进度"></progress><span class="achievement-progress">${m.progress} / ${m.target} ${m.unit}</span></button>`).join('')}</div><p class="achievement-footnote">依据当前浏览器中的议会与账单记录自动点亮；已有历史同样计入。冷静期结束或重新决定后，已达成的「交给时间」仍然保留。</p></section>`;
}
function ensureAchievementToastHost(){
  let host=$('#achievement-toasts');
  if(!host){host=document.createElement('div');host.id='achievement-toasts';host.className='achievement-toasts';host.setAttribute('aria-live','polite');document.body.appendChild(host)}
  return host;
}
function pumpAchievementToasts(){
  if(achievementToastActive||!achievementToastQueue.length)return;
  const medal=achievementToastQueue.shift();
  achievementToastActive=true;
  const el=document.createElement('div');
  el.className='achievement-toast';el.setAttribute('role','status');
  el.innerHTML=`<span class="achievement-toast-medal"><img src="${medal.icon}" alt="" width="52" height="52"></span><span class="achievement-toast-copy"><small>ACHIEVEMENT UNLOCKED · 成就解锁</small><strong>${esc(medal.name)}</strong><em>${esc(medal.latin)} · 勋章已点亮</em></span><button type="button" class="achievement-toast-close" aria-label="关闭成就提示">×</button>`;
  ensureAchievementToastHost().appendChild(el);
  let closed=false,timer;
  const finish=()=>{if(closed)return;closed=true;clearTimeout(timer);el.classList.add('is-leaving');setTimeout(()=>{el.remove();achievementToastActive=false;pumpAchievementToasts()},360)};
  timer=setTimeout(finish,5200);
  el.querySelector('.achievement-toast-close').addEventListener('click',finish);
}
function queueAchievementToast(medal){
  achievementToastQueue.push(medal);
  pumpAchievementToasts();
}
function checkAchievements(){
  const medals=evaluateAchievements(ledger);
  if(!Array.isArray(achievementSeen)){
    achievementSeen=medals.filter(m=>m.unlocked).map(m=>m.id);
    save(ACHIEVEMENTS_SEEN_KEY,achievementSeen);
    return;
  }
  const newly=medals.filter(m=>m.unlocked&&!achievementSeen.includes(m.id));
  if(!newly.length)return;
  achievementSeen=[...achievementSeen,...newly.map(m=>m.id)];
  save(ACHIEVEMENTS_SEEN_KEY,achievementSeen);
  newly.forEach(queueAchievementToast);
}
function showAchievement(id){
  const m=evaluateAchievements(ledger).find(m=>m.id===id);if(!m)return;
  $('#detail-content').innerHTML=`<article class="achievement-detail ${m.unlocked?'is-unlocked':'is-locked'}"><p class="eyebrow">${m.latin}</p><img class="achievement-detail-art" src="${m.icon}" alt="${esc(m.symbol)}勋章" width="230" height="230"><h2>${esc(m.name)}</h2><p class="achievement-detail-symbol">${esc(m.symbol)}</p><p class="achievement-detail-condition">${esc(m.condition)}</p><p class="achievement-detail-status">${m.unlocked?'✦ 勋章已点亮':'尚未解锁 · 每一步认真，都算数'}<br>当前进度：${m.progress} / ${m.target} ${m.unit}</p><progress class="achievement-meter" max="${m.target}" value="${m.progress}" aria-label="${esc(m.name)}达成进度"></progress></article>`;
  $('#detail-dialog').showModal();
}
function renderProfile(){
  const kept=ledger.history.filter(h=>h.decision?.vote!=='买').reduce((n,h)=>n+(Number(h.price)||0),0);
  const recent=ledger.history.slice(0,4);
  const history=recent.length?recent.map(h=>`<div class="profile-history-row"><button type="button" data-action="record" data-id="${h.id}">${esc(h.product)}</button><span>${esc(h.decision?.vote||'—')}</span><time>${date(h.createdAt)}</time></div>`).join(''):'<p class="profile-empty">还没有议会记录。去门廊召集第一场议会，让先贤替你看清这件东西。</p>';
  $('#profile-view').innerHTML=`<section class="profile-page"><div class="forum-topline"><a class="forum-back" href="#forum">← 返回门廊</a><span>THE CITIZEN · YOUR SEAT</span><span>${esc(date(profile.since))} 入席</span></div><div class="profile-title"><div><p class="eyebrow">PERSONAL HOME · CIVIS</p><h1>个人主页</h1></div><div class="profile-intro"><p>把每一次犹豫，<br>留给同一张议事桌。</p><button type="button" class="profile-achievement-link" data-action="show-achievements">成就勋章 →</button></div></div><div class="profile-layout"><aside class="profile-portrait"><span class="portal-art" style="width:210px;max-width:100%;margin:0 auto"><img src="/assets/hub-emblems.png" alt="" width="724" height="724"></span><h2>${esc(profile.name)}</h2><p>CITIZEN · EST. MMXXVI</p><blockquote>“${esc(profile.motto)}”</blockquote></aside><div><div class="profile-stats"><div class="profile-stat"><strong>${String(ledger.history.length).padStart(2,'0')}</strong><span>已开的议会</span></div><div class="profile-stat"><strong>¥ ${money(kept)}</strong><span>没有花出去</span></div><div class="profile-stat"><strong>¥ ${money(available())}</strong><span>当前可用闲钱</span></div></div><form id="profile-form" class="profile-form"><h2>你的席位</h2><label>称呼<input name="name" required maxlength="30" value="${esc(profile.name)}" placeholder="让先贤知道怎么称呼你"></label><label>一句话<textarea name="motto" rows="2" maxlength="120" placeholder="写下你希望自己记住的一句话">${esc(profile.motto)}</textarea></label><label class="profile-motion"><input type="checkbox" name="motion" ${prefs.motion?'checked':''}> 保留动效与音效</label><button class="button primary" type="submit">保存身份</button><span id="profile-save-note" class="profile-save-note">身份与偏好只保存在当前浏览器</span></form>${devPanelMarkup()}<div class="profile-history"><header><h2>最近的议会</h2><a href="#ledger">查看全部账单 →</a></header>${history}</div></div></div>${achievementsMarkup()}</section>`;
}
function showRecord(id){
const h=ledger.history.find(h=>h.id===id);if(!h)return;const pack=packOf(h.packId),size=h.councilSize||h.seats?.length||7;const seatStrip=(h.seats||[]).map(sid=>{const c=pack.members.find(m=>m.id===sid);const ci=c?pack.members.indexOf(c):0;return `<span class="record-seat">${c?portrait(c,ci):friendSilhouette}<small>${c?esc(c.name):'好友'}</small></span>`}).join('');$('#detail-content').innerHTML=`<p class="eyebrow">THE ARCHIVE</p><div class="record-heading"><h2>${esc(h.product)}</h2><p>${date(h.createdAt)} · ¥ ${money(h.price)} · 你的决定：${h.decision.vote}</p></div><p class="record-pack">${esc(h.packName||pack.name)} · ${size} 席</p><div class="record-council pack-${pack.theme}">${seatStrip}</div><p class="user-reason">${esc(h.reason)}</p>${ballotMarkup(h)}<h3 style="margin-top:30px">完整质询记录</h3>${transcriptMarkup(h.answers)}`;$('#detail-dialog').showModal()}
async function renderFriend(id,token){const root=$('#friend-view');try{const f=await api(`/api/rooms/${id}/friend`,{friendToken:token});const inquiry=f.answers.length?`<p class="eyebrow">THE INQUIRY SO FAR</p>${transcriptMarkup(f.answers)}`:'';let body='';if(f.state==='CREATED'){body=`<div class="friend-locked"><h2>议会尚未开庭</h2><p>主持人开启质询后，你就可以提出自己的问题。</p><button class="button" data-action="friend-refresh" style="margin-top:20px">刷新状态</button></div>`}else if(f.state==='QUESTIONING'){if(!f.questionAsked){body=`<form id="friend-question-form" class="friend-form" data-id="${id}" data-token="${token}"><p class="eyebrow">YOUR QUESTION</p><label>你的称呼<input name="name" required maxlength="30" value="${esc(f.name)}" placeholder="让主持人知道怎么称呼你"></label><label>你的质询<textarea name="question" required maxlength="500" rows="3" placeholder="写一个你真正想问的问题…"></textarea></label><p class="muted" style="font-size:11px">提交后不可修改。主持人会按席位顺序回答，全部质询结束后才开始表决。</p><button class="button primary w-full" type="submit">提交我的质询 <i data-icon="arrow-right"></i></button></form>${inquiry}`}else{body=`<div class="friend-locked"><h2>你的质询已提交</h2><p class="friend-question">“${esc(f.question)}”</p><p>等待主持人回答这一问。全部质询结束后，才会进入表决。</p><button class="button" data-action="friend-refresh" style="margin-top:20px">刷新状态</button></div>${inquiry}`}}else if(f.state==='QUESTION_DONE'){body=`<div class="friend-locked"><h2>全部质询已答复</h2><p>等待主持人进入表决。表决开始后，你可以查看完整问答并提交自己的观点。</p><button class="button" data-action="friend-refresh" style="margin-top:20px">刷新状态</button></div>${inquiry}`}else{body=`<p class="eyebrow">THE COMPLETE INQUIRY</p>${transcriptMarkup(f.answers)}${f.submitted?'<div class="friend-locked"><h2>你的观点已封存</h2><p>感谢你的独立意见。提交后无法修改<br>其余议员的观点与票数将仅向主持人揭晓</p></div>':f.state==='WAIT_FRIEND_SUBMIT'?`<form id="friend-form" class="friend-form" data-id="${id}" data-token="${token}"><p class="eyebrow">YOUR PERSONAL VERDICT</p><label>你的称呼<input name="name" required maxlength="30" value="${esc(f.name)}" placeholder="让朋友知道这是谁的意见"></label><label>你的观点<textarea name="opinion" required maxlength="1500" rows="4" placeholder="结合上面的问答，诚实地写下你的理由"></textarea></label><div class="friend-votes">${votes.map(v=>`<label><input type="radio" name="vote" value="${v}" required>${v}</label>`).join('')}</div><p class="muted" style="font-size:11px">提交后立即锁定，不可修改</p><button class="button primary w-full" type="submit">封存我的观点 <i data-icon="lock"></i></button></form>`:''}`}const sameInvitation=root.dataset.invitation===`${id}/${token}`;root.dataset.invitation=`${id}/${token}`;root.innerHTML=`<section class="friend-page invitation-scroll pack-${f.pack}${sameInvitation?' scroll-settled':''}"><span class="scroll-roller" aria-hidden="true"></span><span class="scroll-roller scroll-roller-bottom" aria-hidden="true"></span><div class="entrance-seal" aria-hidden="true">S</div><div class="invitation-heading"><p class="eyebrow">THE SENATE · AN INVITATION</p><h1>你的席位，已为你留好</h1><p class="muted">受邀入席，以独立之声，回应朋友的犹疑。<br>你看不到其他议员的观点与票数。</p></div><div class="friend-intro"><div class="flex items-center justify-between" style="gap:20px"><h2>${esc(f.product)}</h2><strong>¥ ${money(f.price)}</strong></div><p>${esc(f.reason)}</p><p class="friend-pack">${esc(f.packName)} · ${f.size} 席</p></div>${body}<footer class="invitation-footer"><span>THE SENATE · SENATVS</span><span>一席独立意见，一份郑重相托</span></footer></section>`;hydrateIcons(root)}catch(e){root.innerHTML=`<div class="error-state"><h2>这场议会暂不可访问</h2><p>${esc(e.message)}</p><a class="button" href="#home">返回首页</a></div>`}}
async function route(){clearBallotReveal();const version=++routing;clearInterval(poll);poll=null;const hash=location.hash||'#home';if(hash.startsWith('#friend/')){setView('friend');const[,id,token]=hash.slice(1).split('/');await renderFriend(id,token);window.scrollTo(0,0);return;}if(hash==='#forum'){setView('home');window.scrollTo(0,0);setPagerPage(2,{instant:true});if(credentials&&!room){roomApi('').then(r=>{if(version===routing){room=r;renderForum()}}).catch(()=>{})}return;}if(hash==='#profile'){setView('profile');renderProfile();window.scrollTo(0,0);return;}if(hash==='#ledger'){setView('ledger');renderLedger();window.scrollTo(0,0);return;}if(hash==='#chamber'){setView('chamber');if(credentials){try{room=await roomApi('');if(version!==routing)return;recordDecision();}catch(e){credentials=null;room=null;save('senate-session-v1',null);toast(e.message)}}renderChamber();window.scrollTo(0,0);return;}setView('home');window.scrollTo(0,0);setPagerPage(0,{instant:true});}
document.addEventListener('click',async event=>{const roleButton=event.target.closest('[data-role]');if(roleButton){selectedRole=roleButton.dataset.role;renderChamber();return;}const seat=event.target.closest('.seat.editable[data-seat]');if(seat){try{await assignSeat(Number(seat.dataset.seat))}catch(e){toast(e.message)}return;}
const packOption=event.target.closest('[data-pack-option]');if(packOption){if(!packOption.disabled)selectFormPack(packOption.dataset.packOption);return;}
const sizeOption=event.target.closest('[data-size-option]');if(sizeOption){selectFormSize(sizeOption.dataset.sizeOption);return;}
const homeLink=event.target.closest('a[href="#home"]');if(homeLink&&homeVisible()){event.preventDefault();goPage(0);return;}
const pageBtn=event.target.closest('[data-goto-page]');if(pageBtn){event.preventDefault();goPage(Number(pageBtn.dataset.gotoPage));return;}
const pagerBtn=event.target.closest('[data-pager]');if(pagerBtn){event.preventDefault();const act=pagerBtn.dataset.pager;if(act==='next')goPage(homePager.page+1);else if(act==='prev')goPage(homePager.page-1);else if(act==='council'){goPage(1);setTimeout(()=>setSlide(4),380)}else goPage(0);return;}
const slideDot=event.target.closest('[data-slide-to]');if(slideDot){event.preventDefault();goSlide(Number(slideDot.dataset.slideTo));return;}
if(event.target.closest('[data-slide-prev]')){event.preventDefault();goSlide(homePager.slide-1);return;}
if(event.target.closest('[data-slide-next]')){event.preventDefault();goSlide(homePager.slide+1);return;}
const sage=event.target.closest('[data-sage]');if(sage){event.preventDefault();showSage(sage.dataset.sage);return;}
const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(el.disabled)return;try{
 if(action==='show-achievements'){$('#achievement-gallery')?.scrollIntoView({behavior:motionOff()?'instant':'smooth',block:'start'});return;}
 if(action==='achievement'){showAchievement(el.dataset.achievement);return;}
 if(action==='toggle-motion'){prefs.motion=!prefs.motion;save('senate-prefs-v1',prefs);applyPrefs();if(!prefs.motion){finishTyping();clearBallotReveal();if(room?.state==='VOTE_FINISHED'&&location.hash==='#chamber')renderChamber();}toast(prefs.motion?'动画已开启':'动画已关闭');return;}
 if(action==='new'||action==='sample'){openProposal(action==='sample');return;}if(action==='enter-council'){openProposal();return;}if(action==='fill-sample'){fillSample();return;}if(action==='close'){el.closest('dialog').close();return;}if(action==='transcript'){showTranscript();return;}if(action==='record'){showRecord(el.dataset.id);return;}if(action==='ledger-tab'){tab=el.dataset.tab;renderLedger();return;}if(action==='friend-refresh'){await route();return;}
 if(action==='dev-test'){const form=$('#dev-form'),status=$('#dev-status');if(!form||!status)return;const key=form.querySelector('[name=key]').value.trim(),model=form.querySelector('[name=model]').value,base=form.querySelector('[name=base]').value.trim();if(!key){status.className='dev-status bad';status.textContent='请先填写 API Key';return}el.disabled=true;status.className='dev-status';status.textContent='正在连接 DeepSeek…';try{const result=await api('/api/dev/test',{method:'POST',body:{key,model,base}});status.className='dev-status ok';status.textContent=`连接成功${result.models?.length?' · '+result.models.slice(0,2).join(' / '):''}`}catch(error){status.className='dev-status bad';status.textContent=`连接失败：${error.message}`}finally{el.disabled=false}return;}
 el.disabled=true;
 if(action==='start'||action==='deliberate'){if(dev.enabled&&!devActive()){toast('开发者模式已开启，请先在个人主页填写 DeepSeek API Key');return}const payload=devPayload();if(payload)showAiLoading(true);try{room=await roomApi(action,payload?{dev:payload}:{});renderChamber();if(room.devWarning)toast(room.devWarning)}finally{if(payload)showAiLoading(false)}}
 if(action==='refresh'){room=await roomApi('');renderChamber();}
 if(action==='copy-invite'){const url=friendHref(room.friends[Number(el.dataset.index)]);try{await navigator.clipboard.writeText(url);toast('邀请链接已复制')}catch{$('#detail-content').innerHTML=`<p class="eyebrow">INVITATION</p><h2 style="font-size:25px">复制好友邀请链接</h2><input id="copy-url" readonly value="${esc(url)}"><p class="desk-note">好友需要能访问此服务地址。本机演示可直接打开好友页。</p>`;$('#detail-dialog').showModal();$('#copy-url').select();}}
 if(action==='decide'){room=await roomApi('decision',{vote:el.dataset.vote,days:Number($('#freeze-days').value)});recordDecision();renderChamber();toast('你的决定已记入账本');}
 if(action==='resolve'){const h=ledger.history.find(h=>h.id===el.dataset.id);if(h?.decision.vote==='暂缓'){h.originalDecision={...h.decision};h.decision={vote:el.dataset.vote,days:0,at:new Date().toISOString()};h.freezeUntil=null;if(el.dataset.vote==='买')entry('expense',h.price,h.product);persistLedger();renderLedger();toast(el.dataset.vote==='买'?'已记录购买，释放冻结预算':'已放弃购买，释放冻结预算');}}
 }catch(e){toast(e.message)}finally{el.disabled=false;}});
document.addEventListener('keydown',e=>{if(e.target.matches('.seat.editable[data-seat]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click()}});
document.addEventListener('change',e=>{if(e.target.id!=='dev-enabled')return;dev.enabled=!!e.target.checked;saveDev();const fields=$('#dev-fields');if(fields)fields.hidden=!dev.enabled;const label=e.target.closest('.dev-toggle')?.querySelector('b');if(label)label.textContent=dev.enabled?'已开启':'未开启';const status=$('#dev-status');if(status){status.className='dev-status '+(devActive()?'ok':'');status.textContent=devActive()?'已开启 · 新议会将由 DeepSeek 生成':(dev.enabled?'请填写 API Key':'未开启 · 使用本地规则')}toast(dev.enabled?'开发者模式已开启':'开发者模式已关闭')});
document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-role]');if(el){selectedRole=el.dataset.role;e.dataTransfer.setData('text/plain',selectedRole);e.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragenter',e=>{const seat=e.target.closest('.seat.editable[data-seat]');if(seat){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';seat.classList.add('dragover')}});
document.addEventListener('dragover',e=>{const seat=e.target.closest('.seat.editable[data-seat]');if(seat){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';seat.classList.add('dragover')}});
document.addEventListener('dragleave',e=>e.target.closest('.seat.editable[data-seat]')?.classList.remove('dragover'));
document.addEventListener('drop',async e=>{const seat=e.target.closest('.seat.editable[data-seat]');if(seat){e.preventDefault();seat.classList.remove('dragover');const role=e.dataTransfer.getData('text/plain');if(membersOf(room.pack).some(c=>c.id===role)||role==='friend'){selectedRole=role;try{await assignSeat(Number(seat.dataset.seat))}catch(err){toast(err.message)}}}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['proposal-form','answer-form','money-form','friend-form','friend-question-form','profile-form','dev-form'].includes(form.id))return;e.preventDefault();const button=form.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;const b=Object.fromEntries(new FormData(form));try{
 if(form.id==='proposal-form'){if(formSeats.length!==formSize)drawFormSeats();const data=await api('/api/rooms',{method:'POST',body:{...b,pack:formPack,size:formSize,seats:[...formSeats]}});const target=Number(b.cash),difference=Math.round((target-available())*100)/100;if(Math.abs(difference)>.001)entry(difference>0?'income':'expense',Math.abs(difference),ledger.initialized?'调整可用预算':'初始可用预算');ledger.initialized=true;persistLedger();room=data.room;credentials={id:room.id,ownerToken:data.ownerToken};save('senate-session-v1',credentials);selectedRole=null;clearBallotReveal();$('#proposal-dialog').close();if(location.hash==='#chamber'){setView('chamber');renderChamber();window.scrollTo(0,0)}else location.hash='chamber';}
 if(form.id==='answer-form'){room=await roomApi('answer',{index:room.answers.length,answer:b.answer});renderChamber();$('#answer-input')?.focus({preventScroll:true});}
 if(form.id==='money-form'){const amount=Number(b.amount);if(!Number.isFinite(amount)||amount<=0||!b.note.trim())throw Error('请输入金额和备注');entry(b.kind,amount,b.note.trim());ledger.initialized=true;persistLedger();renderLedger();toast('已记入收支账本');}
 if(form.id==='profile-form'){const name=String(b.name||'').trim();if(!name)throw Error('请填写你的称呼');profile={...profile,name,motto:String(b.motto||'').trim()};save('senate-profile-v1',profile);prefs.motion=!!b.motion;save('senate-prefs-v1',prefs);applyPrefs();renderProfile();toast('身份已保存');}
 if(form.id==='dev-form'){dev={enabled:!!$('#dev-enabled')?.checked,key:String(b.key||'').trim(),model:b.model==='deepseek-reasoner'?'deepseek-reasoner':'deepseek-chat',base:String(b.base||'https://api.deepseek.com').trim()||'https://api.deepseek.com'};saveDev();const status=$('#dev-status');if(status){status.className='dev-status '+(devActive()?'ok':'');status.textContent=devActive()?'已保存 · 新议会将由 DeepSeek 生成':'已保存 · 填写 Key 后开启'}toast('开发者设置已保存');}
 if(form.id==='friend-form'){await api(`/api/rooms/${form.dataset.id}/friend`,{method:'POST',body:b,friendToken:form.dataset.token});await renderFriend(form.dataset.id,form.dataset.token);toast('你的观点已封存');}
 if(form.id==='friend-question-form'){await api(`/api/rooms/${form.dataset.id}/ask`,{method:'POST',body:{name:b.name,question:b.question},friendToken:form.dataset.token});await renderFriend(form.dataset.id,form.dataset.token);toast('你的质询已提交');}
 }catch(err){if(form.id==='proposal-form')$('#proposal-error').textContent=err.message;else toast(err.message)}finally{button.disabled=false;}});
window.addEventListener('hashchange',route);window.addEventListener('pagehide',()=>clearInterval(poll));window.addEventListener('storage',e=>{if(e.key==='senate-ledger-v1'){ledger=load('senate-ledger-v1',ledger);achievementSeen=load(ACHIEVEMENTS_SEEN_KEY,achievementSeen);checkAchievements();if(location.hash==='#ledger')renderLedger();if(location.hash==='#profile')renderProfile()}else if(e.key===ACHIEVEMENTS_SEEN_KEY){achievementSeen=load(ACHIEVEMENTS_SEEN_KEY,achievementSeen)}});
function wheelPager(event){if(!homeVisible()||dialogOpen()||event.ctrlKey)return;event.preventDefault();if(homePager.locked)return;const ax=Math.abs(event.deltaX),ay=Math.abs(event.deltaY);if(ax>ay*1.1&&homePager.page===1){if(ax>12)slideBy(event.deltaX>0?1:-1);return}homePager.wheelAcc+=event.deltaY;clearTimeout(homePager.wheelTimer);homePager.wheelTimer=setTimeout(()=>{homePager.wheelAcc=0},170);if(Math.abs(homePager.wheelAcc)>=24){const dir=homePager.wheelAcc>0?1:-1;homePager.wheelAcc=0;goPage(homePager.page+dir)}}
document.addEventListener('wheel',wheelPager,{passive:false});
let pagerPointer=null;
document.addEventListener('pointerdown',event=>{if(!homeVisible()||dialogOpen()||event.button>0)return;if(event.target.closest('button,a,input,textarea,select'))return;pagerPointer={x:event.clientX,y:event.clientY,dx:0,dy:0};if(homePager.page===1&&$('#ritual-slider')?.contains(event.target)){homePager.dragging=true;$('#ritual-slider').classList.add('dragging');$('#ritual-track').classList.add('dragging')}},{passive:true});
document.addEventListener('pointermove',event=>{if(!pagerPointer)return;pagerPointer.dx=event.clientX-pagerPointer.x;pagerPointer.dy=event.clientY-pagerPointer.y;if(homePager.dragging&&Math.abs(pagerPointer.dx)>Math.abs(pagerPointer.dy)){const track=$('#ritual-track');if(track)track.style.transform=`translateX(calc(${-homePager.slide*100}% + ${pagerPointer.dx}px))`}},{passive:true});
function endPagerPointer(){if(!pagerPointer)return;const{dx,dy}=pagerPointer;pagerPointer=null;const track=$('#ritual-track'),slider=$('#ritual-slider');if(homePager.dragging){homePager.dragging=false;slider?.classList.remove('dragging');track?.classList.remove('dragging')}if(Math.abs(dx)>Math.abs(dy)*1.2&&Math.abs(dx)>55&&homePager.page===1){slideBy(dx<0?1:-1);return}if(Math.abs(dy)>Math.abs(dx)*1.2&&Math.abs(dy)>55){goPage(homePager.page+(dy<0?1:-1));return}if(track)setSlide(homePager.slide)}
document.addEventListener('pointerup',endPagerPointer,{passive:true});
document.addEventListener('pointercancel',endPagerPointer,{passive:true});
document.addEventListener('keydown',event=>{if(!homeVisible()||dialogOpen()||event.altKey||event.ctrlKey||event.metaKey)return;if(event.target instanceof Element&&event.target.matches('input,textarea,select'))return;if(event.key==='ArrowDown'||event.key==='PageDown'){event.preventDefault();goPage(homePager.page+1)}else if(event.key==='ArrowUp'||event.key==='PageUp'){event.preventDefault();goPage(homePager.page-1)}else if(event.key==='ArrowRight'&&homePager.page===1){event.preventDefault();slideBy(1)}else if(event.key==='ArrowLeft'&&homePager.page===1){event.preventDefault();slideBy(-1)}});
applyPrefs();splitHero();renderSlideVoices(featuredPack);setSlide(0);hydrateIcons();route();initHeroLive();checkAchievements();
